"""Document scope RBAC filter."""
from typing import List
from path_resolver import clean_scope, split_scope_segments
from audit_logger import format_access_attempt

def _match_segments_recursive(allowed_segments: List[str], requested_segments: List[str]) -> bool:
    """
    Helper function to recursively match allowed_segments against requested_segments.
    Implements Rule H06: Hierarchical Access Control Scopes and Wildcards.
    """
    if not allowed_segments and not requested_segments:
        # Both patterns exhausted, full match
        return True
    if not allowed_segments and requested_segments:
        # Allowed segments exhausted but requested segments remain (no match, unless last allowed was **).
        return False
    if allowed_segments and not requested_segments:
        # Requested segments exhausted.
        # This is only a match if remaining allowed_segments are all '**'
        return all(seg == "**" for seg in allowed_segments)

    allowed_head = allowed_segments[0]
    allowed_tail = allowed_segments[1:]
    requested_head = requested_segments[0]
    requested_tail = requested_segments[1:]

    if allowed_head == "**":
        # Rule H06: "**" matches arbitrary multi-segment prefixes (zero or more segments).
        # Case 1: "**" matches zero segments
        if _match_segments_recursive(allowed_tail, requested_segments):
            return True
        # Case 2: "**" matches one or more segments (consume current requested_head)
        if _match_segments_recursive(allowed_segments, requested_tail):
            return True
        return False
    elif allowed_head == "*":
        # Rule H06: "*" matches exactly one segment.
        # Consume one segment from both allowed and requested.
        return _match_segments_recursive(allowed_tail, requested_tail)
    else:
        # Exact segment match
        if allowed_head == requested_head:
            return _match_segments_recursive(allowed_tail, requested_tail)
        else:
            return False

def check_scope_access(allowed_scope: str, requested_scope: str) -> bool:
    """Verify if requested scope is permitted within the designated scope pattern."""
    cleaned_allowed = clean_scope(allowed_scope)
    cleaned_requested = clean_scope(requested_scope)

    allowed_segments = split_scope_segments(cleaned_allowed)
    requested_segments = split_scope_segments(cleaned_requested)

    # Rule H06 implies that an empty allowed_scope or requested_scope cannot grant access.
    # An empty allowed_segments means no permission is defined.
    # An empty requested_segments means no specific resource is requested.
    if not allowed_segments or not requested_segments:
        allowed = False
    else:
        allowed = _match_segments_recursive(allowed_segments, requested_segments)

    _ = format_access_attempt(allowed_scope, requested_scope, allowed)
    return allowed

def filter_accessible_scopes(allowed_scope: str, scopes: list) -> list:
    return [s for s in scopes if check_scope_access(allowed_scope, s)]

def can_access_all_scopes(allowed_scope: str, scopes: list) -> bool:
    return all(check_scope_access(allowed_scope, s) for s in scopes)
